from pathlib import Path
import base64,json

out=Path(__file__).resolve().parent
root=out.parents[1]
faces=[
 ('Patua','Patua One','400 · reference','Round dots, soft slabs, and a compact silhouette.',root/'packages/web/public/fonts/patua-one-latin.woff2'),
 ('Fraunces','Fraunces','600 · expressive','More character in the shoulders and serifs. Warm and less mechanical.',out/'fonts/Fraunces.woff2'),
 ('Lora','Lora','600 · literary','Curved details with a lighter touch. Friendly without feeling playful.',out/'fonts/Lora.woff2'),
 ('Literata','Literata','600 · bookish','Open and readable, like a trusted reading companion.',out/'fonts/Literata.woff2'),
 ('Bree','Bree Serif','400 · informal','Rounded and approachable. The closest alternative to Patua’s warmth.',out/'fonts/Bree.woff2'),
 ('DM','DM Serif Display','400 · elegant','More contrast between thick and thin strokes. Refined, but less sturdy at small sizes.',out/'fonts/DM.woff2'),
]
fonts='\n'.join("@font-face{font-family:'%s';src:url(data:font/woff2;base64,%s) format('woff2');font-weight:400;}"%(key,base64.b64encode(file.read_bytes()).decode())for key,_,_,_,file in faces)
glyphs={
 'folio':'<svg viewBox="0 0 40 40" aria-hidden="true"><path d="M18 12C13 7 7 6 3 7v23c5-1 10 1 15 5V12Zm4 0c5-5 11-6 15-5v23c-5-1-10 1-15 5V12Z" fill="currentColor"/></svg>',
 'world':'<svg viewBox="0 0 40 40" aria-hidden="true"><g fill="none" stroke="currentColor" stroke-width="3.6" stroke-linecap="round"><circle cx="20" cy="20" r="15"/><path d="M20 5c-10 8-10 22 0 30M20 5c10 8 10 22 0 30M5 20h30"/></g></svg>',
 'weave':'<svg viewBox="0 0 40 40" aria-hidden="true"><g fill="none" stroke="currentColor" stroke-width="5" stroke-linecap="round" stroke-linejoin="round"><path d="M6 15h20a8 8 0 0 1 0 16h-6M34 25H14a8 8 0 0 1 0-16h6"/></g></svg>',
}
ideas=[
 ('folio','Open folio','Language, reading, and the book that connects the subjects.','Two opening pages. The broad silhouette stays clear beside the name. My strongest starting point.'),
 ('world','Shared world','Science, mathematics, geography, and understanding our surroundings.','A circle divided by simple curves. Familiar symbolism, with more detail to manage at small sizes.'),
 ('weave','Interwoven learning','Patterns, making, and connections between learning areas.','Two continuous strips, with a nod to weaving. Less literal; its meaning needs the surrounding brand story.'),
]
def mark(key='Patua',extra=''):
 return f'<span class="mark {extra}" style="--face:{key}">hiraia<span class="glyph" data-glyph>{glyphs["folio"]}</span></span>'
cards=''.join(f'<button class="type-card {"selected" if key=="Patua" else ""}" data-font="{key}" aria-pressed="{str(key=="Patua").lower()}"><span class="card-heading"><b>{name}</b><span>{weight}</span></span><span class="type-display">{mark(key)}</span><span class="description">{desc}</span>{mark(key,"small-mark")}<span class="choose">Try this serif ↗</span></button>'for key,name,weight,desc,_ in faces)
symbols=''.join(f'<button class="symbol-card {"selected" if key=="folio" else ""}" data-symbol="{key}" aria-pressed="{str(key=="folio").lower()}"><span class="symbol-icon">{glyphs[key]}</span><span class="symbol-title">{name}</span><span class="subjects">{subject}</span><span class="description">{desc}</span></button>'for key,name,subject,desc in ideas)
css='''
*{box-sizing:border-box}body{--ink:#1c3b2e;--paper:#f5ecd6;--accent:#bd8928;--mark-size:80px;margin:0;background:var(--paper);color:var(--ink);font-family:system-ui,-apple-system,sans-serif}main{max-width:1230px;margin:auto;padding:36px 38px 44px}.top{display:flex;justify-content:space-between;align-items:center;border-bottom:1px solid #1c3b2e33;padding-bottom:20px}.mini{font:33px Patua;letter-spacing:-.025em}.eyebrow{font-size:10px;letter-spacing:.13em;text-transform:uppercase}.top p{font-size:12px;margin:5px 0 0;color:#58705f}h1{font-size:32px;font-weight:500;letter-spacing:-.035em;line-height:1.2;margin:28px 0 12px}.intro{max-width:780px;font-size:15px;line-height:1.6;color:#506354;margin:0 0 24px}h2{font-size:18px;font-weight:550;margin:0}.section-intro{font-size:13px;line-height:1.55;color:#586c5b;margin:8px 0 17px}.symbols,.types{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px}button{font:inherit;color:inherit;cursor:pointer;background:transparent}button:focus-visible{outline:3px solid #bd8928;outline-offset:4px}.symbol-card{border:1px solid #1c3b2e33;border-radius:8px;padding:18px;text-align:left;display:grid;grid-template-columns:44px 1fr;gap:8px 12px}.selected{border-color:#1c3b2e!important;box-shadow:inset 0 0 0 1px #1c3b2e}.symbol-card.selected{background:#eee4ca}.symbol-icon{grid-row:1/3;width:40px;height:40px;color:var(--accent)}svg{display:block;width:100%;height:100%}.symbol-title{font-size:16px;font-weight:550}.subjects{font-size:12px;line-height:1.5;color:#506354}.description{display:block;font-size:13px;line-height:1.6;color:#536956}.symbol-card .description{grid-column:1/-1;margin-top:4px}.toolbar{display:flex;justify-content:space-between;align-items:center;gap:16px;border-top:1px solid #1c3b2e33;padding-top:24px;margin-top:26px}.controls{display:flex;align-items:center;gap:16px}.controls button{border:1px solid #1c3b2e55;border-radius:25px;padding:7px 12px;font-size:12px}.controls label{font-size:12px;display:flex;align-items:center;gap:8px}input{accent-color:#1c3b2e;width:100px}.type-card{display:block;position:relative;min-width:0;text-align:left;border:1px solid #1c3b2e33;border-radius:8px;padding:16px 19px}.card-heading{display:flex;justify-content:space-between;align-items:baseline;gap:8px;font-size:14px}.card-heading b{font-weight:550}.card-heading>span{font-size:10px;color:#58705f}.type-display{height:126px;display:flex;align-items:center;justify-content:center}.mark{display:inline-flex;align-items:baseline;font-family:var(--face,Patua);font-size:var(--mark-size);font-weight:400;line-height:1;letter-spacing:-.027em;white-space:nowrap}.glyph{width:.27em;height:.27em;margin-left:.065em;position:relative;top:-.45em;display:inline-block;flex-shrink:0;color:var(--accent)}.type-card .description{min-height:42px;margin-bottom:14px}.small-mark{font-size:29px}.choose{float:right;font-size:10px;margin-top:14px;color:#58705f}.status{font-size:13px;color:#536956;margin:17px 0}.tryout{display:grid;grid-template-columns:1fr 1fr;gap:16px}.context{border:1px solid #1c3b2e33;border-radius:8px;min-height:180px;padding:23px 28px}.context.dark{background:var(--ink);color:var(--paper)}.context .mark{font-size:65px;margin-top:22px}.context.dark .glyph{color:inherit}.context p{font-size:12px;line-height:1.5;opacity:.75;margin:16px 0 0}.context.small .mark{font-size:32px}.nav{display:flex;justify-content:space-between;align-items:center}.nav-label{font-size:12px;margin-top:22px}footer{font-size:11px;line-height:1.7;color:#58705f;margin-top:27px;padding-top:17px;border-top:1px solid #1c3b2e33}a{color:inherit}body.mono .glyph,body.mono .symbol-icon{color:inherit}@media(max-width:1000px){.types{grid-template-columns:repeat(2,minmax(0,1fr))}.symbols{grid-template-columns:1fr}.toolbar{align-items:start;flex-direction:column}.symbol-card .description{grid-column:2}}@media(max-width:620px){main{padding:24px 20px}.types,.tryout{grid-template-columns:1fr}h1{font-size:28px}.controls{flex-wrap:wrap}.symbol-card .description{grid-column:1/-1}.type-card .description{min-height:0}.top{gap:15px}.eyebrow{font-size:9px}}
'''
html=f'''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>hiraia — serifs & curriculum symbols</title><style>{fonts}{css}</style><main><div class="top"><div><span class="mini">hiraia</span><p>Wordmark refinement</p></div><div class="eyebrow">Study 02 / Serif &amp; symbol</div></div><h1>Round dots. Softer serifs. A symbol with a reason.</h1><p class="intro">Patua One stays as our reference. This round compares five other serifs and three curriculum-inspired glyphs. No asterisks, flowers, or sparkles.</p><h2>1. Choose the idea behind the glyph</h2><p class="section-intro">Each symbol updates every specimen below. Shared ideas across learning areas, rather than one tiny icon per subject.</p><div class="symbols">{symbols}</div><div class="toolbar"><h2>2. Compare the serifs</h2><div class="controls"><label>Type size <input id="size" type="range" min="50" max="88" value="80" aria-label="Wordmark specimen size"></label><button id="mono" aria-pressed="false">Single-colour view</button></div></div><p class="section-intro">The same name and glyph at the same type size. Select a serif to see it in the larger and website-header examples.</p><div class="types">{cards}</div><p class="status" id="status" aria-live="polite">Selected: Patua One + Open folio</p><div class="tryout"><div class="context dark"><div class="eyebrow">One colour / reversed</div>{mark(extra='chosen')}<p>The symbol must hold up without gold doing the work.</p></div><div class="context small"><div class="eyebrow">In a website header</div><div class="nav">{mark(extra='chosen')}<span class="nav-label">About&nbsp;&nbsp; Download ↗</span></div><p>Check the dots, spacing, and raised glyph at everyday size.</p></div></div><footer>Font specimens from Google Fonts; custom SVG glyph studies. Concepts for refinement, before final letterform drawing. Curriculum reference: <a href="https://www.deped.gov.ph/matatagcurriculumk147/">DepEd MATATAG learning-area guides</a>. The symbolism is our design interpretation; the marks do not assign a fixed number of subjects.</footer></main><script>
const glyphs={json.dumps(glyphs)},fontNames={json.dumps({key:name for key,name,*_ in faces})},symbolNames={json.dumps({key:name for key,name,*_ in ideas})};
let font='Patua',symbol='folio';
function update(){{document.querySelectorAll('[data-glyph]').forEach(e=>e.innerHTML=glyphs[symbol]);document.querySelectorAll('.chosen').forEach(e=>e.style.setProperty('--face',font));document.querySelectorAll('[data-font]').forEach(e=>{{const on=e.dataset.font===font;e.classList.toggle('selected',on);e.setAttribute('aria-pressed',String(on));e.querySelector('.choose').textContent=(on?'Selected':'Try this serif')+' ↗';}});document.querySelectorAll('[data-symbol]').forEach(e=>{{const on=e.dataset.symbol===symbol;e.classList.toggle('selected',on);e.setAttribute('aria-pressed',String(on));}});document.getElementById('status').textContent='Selected: '+fontNames[font]+' + '+symbolNames[symbol];}}
document.querySelectorAll('[data-font]').forEach(e=>e.onclick=()=>{{font=e.dataset.font;update();}});document.querySelectorAll('[data-symbol]').forEach(e=>e.onclick=()=>{{symbol=e.dataset.symbol;update();}});document.getElementById('size').oninput=e=>document.body.style.setProperty('--mark-size',e.target.value+'px');document.getElementById('mono').onclick=e=>{{const on=document.body.classList.toggle('mono');e.target.setAttribute('aria-pressed',String(on));}};update();
</script></html>'''
(out/'index.html').write_text(html)
print(out/'index.html')
